<?php require __DIR__.'/bootstrap.php';require_login();$error='';$owners=[];if(is_admin())$owners=db()->query('SELECT id,name,email FROM users WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=[];foreach(['title','brand','model','fuel_type','transmission','description'] as $f)$data[$f]=trim($_POST[$f]??'');$year=(int)($_POST['year']??0);$price=(float)($_POST['price']??0);$mileage=(int)($_POST['mileage']??0);$owner=is_admin()?(int)($_POST['owner_id']??0):current_user()['id'];if(!$owner||!$data['title']||!$data['brand']||!$data['model']||$year<1950||$year>date('Y')+1||$price<=0||!$data['fuel_type']||!$data['transmission']||!$data['description']){$error='Please complete all required car details correctly.';}elseif(count($_FILES['images']['name']??[])>10){$error='You can upload up to 10 images.';}else{try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO cars(owner_id,created_by_id,title,brand,model,year,price,mileage,fuel_type,transmission,description) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$owner,current_user()['id'],$data['title'],$data['brand'],$data['model'],$year,$price,$mileage?:null,$data['fuel_type'],$data['transmission'],$data['description']]);$car=(int)$pdo->lastInsertId();$files=$_FILES['images']??null;if($files){$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$finfo=new finfo(FILEINFO_MIME_TYPE);$count=0;foreach($files['tmp_name'] as $i=>$tmp){if($files['error'][$i]===UPLOAD_ERR_NO_FILE)continue;if($files['error'][$i]!==UPLOAD_ERR_OK||$files['size'][$i]>5*1024*1024)throw new RuntimeException('Each image must be under 5 MB.');$mime=$finfo->file($tmp);if(!isset($allowed[$mime]))throw new RuntimeException('Only JPG, PNG, or WebP images are allowed.');$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$path=__DIR__.'/uploads/'.$name;if(!move_uploaded_file($tmp,$path))throw new RuntimeException('Image upload failed.');$pdo->prepare('INSERT INTO car_images(car_id,image_path,sort_order) VALUES(?,?,?)')->execute([$car,'uploads/'.$name,++$count]);}}$pdo->commit();flash('Car listing published.');redirect('manage-cars.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'Could not save the car. Please try again.';}}}
page_top('Add car');?><form class="form-card" method="post" enctype="multipart/form-data"><h1>Add a car</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><input type="hidden" name="csrf" value="<?=csrf_token()?>"><?php if(is_admin()):?><label>Listing owner (dealer)</label><select name="owner_id" required><option value="">Choose dealer</option><?php foreach($owners as $o):?><option value="<?=$o['id']?>"><?=e($o['name'])?> — <?=e($o['email'])?></option><?php endforeach?></select><?php endif?><div class="form-grid"><div><label>Title</label><input name="title" required></div><div><label>Brand</label><input name="brand" required></div><div><label>Model</label><input name="model" required></div><div><label>Year</label><input name="year" type="number" min="1950" max="<?=date('Y')+1?>" required></div><div><label>Price</label><input name="price" type="number" min="1" required></div><div><label>Mileage (km)</label><input name="mileage" type="number" min="0"></div><div><label>Fuel type</label><select name="fuel_type" required><option>Petrol</option><option>Diesel</option><option>CNG</option><option>Electric</option><option>Hybrid</option></select></div><div><label>Transmission</label><select name="transmission" required><option>Manual</option><option>Automatic</option><option>AMT</option></select></div></div><label>Description</label><textarea name="description" required></textarea><label>Car images (up to 10; JPG, PNG, or WebP; 5 MB each)</label><input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple><button class="button">Publish listing</button></form><?php page_bottom();
